bool canSegment(String s, String dict) {
  if (s.isEmpty) return false;
  List<String> words = dict.split(' ');
  Set<String> wordSet = words.toSet();

  List<String> tokens = s.split(' ');
  List<bool> dp = List.filled(tokens.length + 1, false);
  dp[0] = true;

  for (int i = 1; i <= tokens.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j]) {
        String sub = tokens.substring(j, i);
        if (wordSet.contains(sub)) {
          dp[i] = true;
          break;
        }
      }
    }
  }
  return dp[tokens.length];
}

int minWords(String s, String dict) {
  if (s.isEmpty) return 0;
  List<String> words = dict.split(' ');
  Set<String> wordSet = words.toSet();

  List<int> dp = List.filled(s.length + 1, 0x3FFFFFFFFFFFFFFF);
  dp[0] = 0;

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      String sub = s.substring(j, i);
      if (wordSet.contains(sub) && dp[j] != 0x3FFFFFFFFFFFFFFF) {
        dp[i] = dp[i] < dp[j] + 1 ? dp[i] : dp[j] + 1;
      }
    }
  }
  return dp[s.length];
}

List<List<int>> wordBreak(String s, List<String> wordDict) {
  if (s.isEmpty) return [];
  wordDict = wordDict.toSet();

  List<List<int>> memo = {};
  List<List<int>> result = [];

  void backtrack(int index, List<int> path) {
    if (index == s.length) {
      result.add(path);
      return;
    }
    for (int i = index; i < s.length; i++) {
      String word = s.substring(index, i + 1);
      if (wordDict.contains(word) && !memo.containsKey(word)) {
        memo[word] = true;
        path.add(word.length - 1);
        backtrack(i + 1, path);
        path.removeLast();
      }
    }
  }

  backtrack(0, []);
  return result;
}

