int minWordBreak(String word, Set<String> dictionary) {

  List<bool> dp = List.filled(word.length + 1, false);
  dp[0] = true; 

  for (int i = 1; i <= word.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && dictionary.contains(word.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }

  int minCount = word.length + 1;
  for (int i = word.length; i >= 0; i--) {
    if (dp[i]) {
      minCount = i + 1;
      break;
    }
  }
