      if (dp[j] && dictionary.contains(word.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }

  List<List<String>> result = [];
  if (!dp[word.length]) return result;

  List<String> path = [];
  void backtrack(int index) {
    if (index == word.length) {
      result.add(List.from(path));
      return;
    }

    for (int j = index; j < word.length; j++) {
      if (dp[j] && dictionary.contains(word.substring(index, j + 1))) {
        path.add(word.substring(index, j + 1));
        backtrack(j + 1);
        path.removeLast();
      }
    }
  }

  backtrack(0);
  return result;
}

