List<String> wordBreak(List<String> wordDict, String s) {
  Set<String> wordSet = wordDict.toSet();
  List<String> wordBreak = [];
  List<bool> dp = List.filled(s.length + 1, false);
  dp[0] = true; 

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && wordSet.contains(s.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }

  if (!dp[s.length]) return wordBreak;

  List<List<String>> segmentations = [];
  List<String> current = [];

  void backtrack(int idx) {
    if (idx == s.length) {
      segmentations.add(List.from(current));
      return;
    }

    for (int j = idx; j < s.length; j++) {
      if (dp[j] && wordSet.contains(s.substring(idx, j + 1))) {
        current.add(s.substring(idx, j + 1));
        backtrack(j + 1);
        current.removeLast();
      }
    }
  }

  backtrack(0);

  return segmentations;
}

int minWordBreak(List<String> wordDict, String s) {
  Set<String> wordSet = wordDict.toSet();
  List<int> dp = List.filled(s.length + 1, s.length + 1);
  dp[0] = 0; 

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (wordSet.contains(s.substring(j, i)) && dp[j] + 1 < dp[i]) {
        dp[i] = dp[j] + 1;
      }
    }
  }

  return dp[s.length] == s.length + 1 ? -1 : dp[s.length];
}

