  ];

  Map<String, bool> dp = {
    for (var s in testStrings) s: false};

  List<int> minWordBreakLen = [0, -1, -1, -1, 0, -1, -1];

  void solve(String s, int i, List<String> wordDict) {
    if (i == s.length) {
      dp[s] = true;
      return;
    }

    for (String word in wordDict) {
      if (s.substring(i, i + word.length) == word) {
        if (dp[s.substring(i + word.length, s.length)]) {
          dp[s] = true;
          return;
        }
        solve(s, i + word.length, wordDict);
      }
    }
  }

  void findMinWordBreakLen(String s, int i, List<String> wordDict) {
    if (i == s.length) {
      minWordBreakLen[0] = 0;
      return;
    }

    for (String word in wordDict) {
      if (s.substring(i, i + word.length) == word) {
        int len = word.length + 1;
        if (minWordBreakLen[len] == -1) {
          findMinWordBreakLen(s, i + word.length, wordDict);
        }
        int lenBefore = minWordBreakLen[len - 1] == -1 ? len : minWordBreakLen[len - 1];
        if (lenBefore == len) {
          minWordBreakLen[len] = lenBefore;
        }
      }
    }
  }

