    String s = testStrings[i];
    List<String> wordDict = s.split(' ');

    solve(s, 0, wordDict);

    findMinWordBreakLen(s, 0, wordDict);

    printResult(s, dp[s]!, minWordBreakLen);
  }

  Map<String, List<String>> wordDict = {
