    for (int i = 1; i <= s.length; i++) {
      for (int j = 0; j < i; j++) {
        if (dp[j] && wordDictSet.contains(s.substring(j, i))) {
          dp[i] = true;
          break;
        }
      }
    }

    if (!dp[s.length]) return [];

    void backtrack(int index, String currentWord, List<String> words) {
      if (index == s.length) {
        results.add(currentWord);
        return;
      }

      for (int j = index; j < s.length; j++) {
        if (dp[j] && wordDictSet.contains(s.substring(index, j + 1))) {
          backtrack(j + 1, currentWord + ' ' + s.substring(index, j + 1), words);
        }
      }
    }

    for (int i = 0; i <= s.length; i++) {
      if (dp[i]) {
        backtrack(i, '', []);
      }
    }

    return results;
  }

  int minWordBreak(String s, Map<String, Set<String>> wordBreak) {
    if (s.isEmpty) return 0;
    final wordDictSet = wordBreak.keys.toSet();
    final dp = List.filled(s.length + 1, 0);
    dp[0] = 0; 

    for (int i = 1; i <= s.length; i++) {
      for (int j = 0; j < i; j++) {
        if (dp[j] < 0 && wordDictSet.contains(s.substring(j, i))) {
          dp[i] = dp[i] < 0 ? i - j : dp[i] + 1;
          break;
        }
      }
    }
    return dp[s.length] < 0 ? 0 : dp[s.length];
  }

