Map<String, int> fn0(List<String> operations, int capacity) {
  List<int> stack = [0];
  List<String> history = [];
  List<List<int>> log = [];
  bool undoAllowed = true;
  int lastUse = 0;

  void flushLog() {
    if (log.isNotEmpty) {
      log[log.length - 1] = [
        ...log[log.length - 1],
        lastUse,
      ];
    }
  }

  void record(List<int> data) {
    history.add('BEGIN');
    for (int i = 0; i < data.length; i++) {
      int val = data[i];
      if (val > 0) {
        stack.add(val);
      } else if (val == 0 && undoAllowed) {
        if (stack.isNotEmpty) {
          int top = stack.removeLast();
          history.add('ADD $top');
        } else {
          history.add('END');
        }
      } else if (val == -1) {
        if (stack.isNotEmpty) {
          int top = stack.removeLast();
          history.add('REMOVE $top');
        }
      } else if (val == -2) {
        if (stack.isNotEmpty) {
          int top = stack.removeLast();
          history.add('UNDO');
        }
      }
    }
    history.add('END');
    log.add(List.from(stack));
    lastUse = stack.isEmpty ? 0 : stack.last;
  }

  for (String op in operations) {
    if (op == 'BEGIN') {
      stack = [0];
      history.add('BEGIN');
    } else if (op == 'ADD') {
      int size = int.parse(op.substring(1));
      if (size <= capacity) {
        stack.add(size);
      } else {
        history.add('END');
      }
    } else if (op == 'REMOVE') {
      int size = int.parse(op.substring(1));
      if (stack.isNotEmpty && stack.last >= size) {
        stack.removeLast();
      }
    } else if (op == 'UNDO') {
      if (history.isNotEmpty) {
        String cmd = history.removeLast();
        if (cmd == 'BEGIN') {
          stack = [0];
        } else if (cmd == 'ADD') {
          int size = stack.removeLast();
          stack.add(size);
        } else if (cmd == 'REMOVE') {
          int size = stack.removeLast();
          stack.add(size);
        } else if (cmd == 'UNDO') {
          undoAllowed = true;
        }
      }
    }
    flushLog();
  }
  return {
    'stack': stack.isEmpty ? 0 : stack.last,
    'history': history.length,
    'log': log.length,
    'lastUse': lastUse,
    'undoAllowed': undoAllowed ? 1 : 0,
  };
}

