  ];

  int n = women.length;
  Map<String, int> womanIndex = {};

  for (int i = 0; i < n; i++) {
    for (String w in women[i]) {
      womanIndex[w] = i;
    }
  }

  Map<String, List<String>> manPrefs = {
    'A': ['W', 'X'],
    'B': ['Y', 'Z'],
    'C': ['A', 'B'],
    'W': ['A', 'B'],
