    'Y': ['C', 'A'],
    'Z': ['Y', 'X'],
  };

  Map<String, String> currentCouple = {};
  List<String> freeMen = men[0];

  while (freeMen.isNotEmpty) {
    String man = freeMen.removeAt(0);

    List<String> choices = manPrefs[man]!;
    List<String> womenFree = [];

    for (String choice in choices) {
      String woman = choice;
      if (!currentCouple.containsKey(woman)) {
        womenFree.add(woman);
      }
    }

    if (womenFree.isEmpty) {
      freeMen.add(man);
      continue;
    }

    int wIndex = womanIndex[womenFree[0]]!;
    List<String> nextWomen = women[wIndex];
    String nextMan = nextWomen[0];

    currentCouple[womenFree[0]] = nextMan;
    freeMen.add(nextMan);
  }

  print('Stable matches:');
  print(currentCouple);
