List<String> fn0(List<String> edits, int maxEdits) {
  List<String> result = [];
  int n = edits.length;
  if (maxEdits >= n) {
    result = edits;
    return result;
  }

  int editDistance(String a, String b) {
    int m = a.length, n = b.length;
    List<List<int>> dp = List.generate(m + 1, (_) => List.filled(n + 1, 0));
    for (int i = 0; i <= m; i++) dp[i][0] = i;
    for (int j = 0; j <= n; j++) dp[0][j] = j;
    for (int i = 1; i <= m; i++) {
      for (int j = 1; j <= n; j++) {
        int cost = a.codeUnitAt(i - 1) == b.codeUnitAt(j - 1) ? 0 : 1;
        dp[i][j] = [dp[i - 1][j] + 1, dp[i][j - 1] + 1, dp[i - 1][j - 1] + cost].reduce((x, y) => x < y ? x : y);
      }
    }
    return dp[m][n];
  }

  void backtrack(int index, int editsLeft) {
    if (editsLeft <= 0 || index >= n) {
      result.add(edits.join(' '));
      return;
    }

    for (int i = index; i < n; i++) {
      if (editDistance(edits[index], edits[i]) <= maxEdits) {
        String current = edits[i];
        edits[index] = current;
        backtrack(index + 1, editsLeft - 1);
      }
    }
  }

  backtrack(0, maxEdits);
  result.sort();
  return result;
}

