int _combinations(int n, int k) {
  if (k <= 0 || k > n) {
    return 0;
  }
  int result = 1;
  int remaining = n - k;
  int current = k;

  while (remaining > 0) {
    result = (result * current) ~/ remaining;
    current--;
    remaining--;
  }

  return result;
}

