List<List<String>> generateCombinations(int k, List<String> items) {
  if (k == 0) {
    return [[]];
  }

  List<List<String>> result = [];
  void backtrack(int start, List<String> current) {
    if (current.length == k) {
      result.add(List<String>.from(current));
      return;
    }
    for (int i = start; i < items.length; i++) {
      current.add(items[i]);
      backtrack(i + 1, current);
      current.removeLast(); 
    }
  }
  backtrack(0, []);
  return result;
}

