void dfsRecursive(int u) {
  if (!disc.containsKey(u)) {
    disc[u] = <int>{};
    low[u] = time++;
    onStack.add(u);
    for (int v in graph[u]!) {
      if (!disc.containsKey(v)) {
        parent[v] = <int>[u];
