      int v;
      do {
        v = onStack.removeLast();
        component.add(v);
        disc[v] = null;
      } while (v != u);
      component.add(u);
      component.sort();
      this.component.add(component);
    }
  }
}

void dfsIterative(int u) {
  final List<int> stack = <int>[];
  final Set<int> visited = <int>{};
  stack.add(u);
  visited.add(u);

  while (stack.isNotEmpty) {
    int v = stack.removeAt(0);

    for (int neighbor in graph[v]!) {
      if (!visited.contains(neighbor)) {
        stack.add(neighbor);
        visited.add(neighbor);
      }
    }
  }

  for (int component in visited) {
    if (component > 0) {
      final List<int> component = <int>[];
      int v;
      do {
        v = component;
        component.add(v);
        disc[v] = null;
      } while (v != component);
      component.add(0);
      component.add(0);
      component[0] = 0;
      this.component.add(component);
    }
  }
}

