  List<List<int>> points = [
    [0, 0],
  ];

  for (int c = 1; c < cols; c++) {
    bool hasChar = false;

    for (int r = 0; r < row.length; r++) {
      String char = row[r];
      if (char.codeUnitAt(0) >= 97 && char.codeUnitAt(0) <= 122) {
        hasChar = true;
        break;
      }
    }

    if (!hasChar) {
      break;
    }

    Set<String> candidates = {};
    for (int r = 0; r < row.length; r++) {
      String char = row[r];
      if (char.codeUnitAt(0) >= 97 && char.codeUnitAt(0) <= 122) {
        candidates.add(char + '-' + '$r');
      }
    }

    if (candidates.isEmpty) {
      break;
    }

    List<String> matches = [];
    for (String cand in candidates) {
      String key = cand + '-' + '$c';
      if (!visited.contains(key)) {
        matches.add(cand);
        visited.add(key);
        break;
      }
    }

    if (matches.isEmpty) {
      break;
