    int maxX = matches[0].length;
    int minY = matches[0].length;
    int maxY = matches[0].length;

    for (String match in matches) {
      int x = match.length;
      int y = match.length;
      if (x < minX) {
        minX = x;
      }
      if (x > maxX) {
        maxX = x;
      }
      if (y < minY) {
        minY = y;
      }
      if (y > maxY) {
        maxY = y;
      }

      for (int d = 0; d < 2; d++) {
        if (d == 0) {
          if (x < minX) {
            xs.add(x);
          }
          if (x > maxX) {
            xs.add(x);
          }
        } else {
          if (y < minY) {
            ys.add(y);
          }
          if (y > maxY) {
            ys.add(y);
          }
        }
      }
    }

    if (xs.isEmpty) {
      break;
    }

    List<List<int>> rect = [
      [minX, minY],
      [maxX, minY],
      [maxX, maxY],
      [minX, maxY],
    ];

    for (int r = 0; r < 4; r++) {
      for (int c = 0; c < 2; c++) {
        if (r == 0 || r == 2 || c == 0 || c == 1) {
          points.add(rect[r][c]);
        }
      }
    }
  }

  if (points.isEmpty) {
    return result;
  }

  points.sort((a, b) {
    for (int d = 0; d < 2; d++) {
      if (a[d] != b[d]) {
        return a[d].compareTo(b[d]);
      }
    }
