    } else if (sensorId == 'elevator') {
      distance = parsed.toDouble();
    }

    double threshold = sensorId == 'hall'
        ? 50.0
        : sensorId == 'stairs'
            ? 20.0
            : 30.0;
    if (distance > threshold) {
