    String seat = parts[0];
    String zone = parts[1];
    if (seat.isEmpty || zone.isEmpty) continue;
    openSeats.add(seat);
    if (zone == '*' || zone == '.') continue;
    zones.add([double.parse(zone[0]), double.parse(zone[1]), double.parse(zone[2]), double.parse(zone[3])]);
  }
  if (openSeats.isEmpty) return minWidth;
  List<List<double>> rects = [];
  for (List<double> zone in zones) {
    double x1 = zone[0];
    double y1 = zone[1];
    double x2 = zone[2];
    double y2 = zone[3];
    double area = (x2 - x1) * (y2 - y1);
    if (area < minWidth) {
      minWidth = area;
    }
    rects.add([x1, y1, x2, y2]);
  }
  List<List<double>> sorted = rects.toList();
  sorted.sort((a, b) {
    double areaA = (a[2] - a[0]) * (a[3] - a[1]);
    double areaB = (b[2] - b[0]) * (b[3] - b[1]);
    if (areaA != areaB) return areaB.compareTo(areaA);
    return a[0].compareTo(b[0]);
  });
  double totalArea = 0.0;
  List<List<double>> buffer = [
    [sorted[0][0], sorted[0][1], sorted[0][2], sorted[0][3]],
    [sorted[0][0], sorted[0][1], sorted[0][3], sorted[0][3]],
    [sorted[0][2], sorted[0][1], sorted[0][3], sorted[0][3]],
    [sorted[0][2], sorted[0][1], sorted[0][0], sorted[0][0]],
  ];
  Set<String> visited = {};
  for (List<double> rect in sorted) {
    for (List<double> bufferRect in buffer) {
      double overlapArea = 0.0;
      if (rect[0] < bufferRect[0] && rect[2] > bufferRect[2] && rect[1] < bufferRect[1] && rect[3] > bufferRect[3]) {
        overlapArea = (rect[2] - rect[0]) * (bufferRect[3] - bufferRect[1]);
      }
      if (overlapArea > 0.0) {
        totalArea += overlapArea;
        break;
      }
    }
    visited.add(rect[0].toString() + ',' + rect[1].toString());
    if (visited.length > 10) break;
  }
  return totalArea / minWidth;
}

