class Vector3 {
  final double x, y, z;

  const Vector3(this.x, this.y, this.z);

  const Vector3.zero() : this(0.0, 0.0, 0.0);

  const Vector3.unit() : this(1.0, 1.0, 1.0);

  const Vector3.random() : this(
        (4 * (Math.random() * 2 - 1)).toDouble(),
        (4 * (Math.random() * 2 - 1)).toDouble(),
        (4 * (Math.random() * 2 - 1)).toDouble(),
      );

  const Vector3.fromList(List<double> parts)
      : this(parts[0], parts[1], parts[2]);

  const Vector3.fromAxisAngle(double x, double y, double z, double theta)
      : this(
          x * Math.cos(theta / 2.0),
          y * Math.cos(theta / 2.0),
          z * Math.cos(theta / 2.0),
        );

  const Vector3.fromConjugateAxisAngle(double x, double y, double z, double theta)
      : this(
          x * Math.cos(theta / 2.0),
          y * Math.cos(theta / 2.0),
          z * Math.cos(theta / 2.0),
          -Math.sin(theta / 2.0),
        );

  const Vector3.fromMatrix(Matrix4x4 mat)
      : this(mat[0], mat[1], mat[2]);

  const Vector3.randomUnit() : this(
        (4 * (Math.random() * 2 - 1)).toDouble(),
        (4 * (Math.random() * 2 - 1)).toDouble(),
        (4 * (Math.random() * 2 - 1)).toDouble(),
      );

  double norm() {
    return x * x + y * y + z * z;
  }

  Vector3 normalized() {
    final double n = norm();
    if (n == 0.0) {
      throw const ArgumentError('Cannot normalize zero vector');
    }
    return const Vector3(x / n, y / n, z / n);
  }

  Vector3 cross(Vector3 other) {
    final double x = x, y = y, z = z;
    final double ax = other.x, ay = other.y, az = other.z;
    return const Vector3(
      y * az - z * ay,
      z * ax - x * az,
      x * ay - y * ax,
    );
  }

  @override
  String toString() {
    return 'v = $x, $y, $z';
  }
}

