  const Quaternion.leftHanded() : this(0.0, 1.0, 0.0, 0.0);

  const Quaternion.rightHanded() : this(0.0, 0.0, 1.0, 0.0);

  const Quaternion.fromAxisAngle(double angle, Vector3 axis) {
    double cos = 0.5 * (1.0 + cos(angle));
    double sin = 0.5 * (1.0 - cos);
    double x = axis.x * sin;
    double y = axis.y * sin;
    double z = axis.z * sin;
    return Quaternion(x, y, z, cos);
  }

  Quaternion operator +(Quaternion other) =>
      Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator -(Quaternion other) =>
      Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(double scalar) =>
      Quaternion(scalar * x, scalar * y, scalar * z, scalar * w);

  Quaternion operator *(Quaternion other) =>
      Quaternion(
          x * other.w - y * other.z - z * other.y + w * other.x,
          y * other.w + x * other.z + z * other.y - w * other.x,
          z * other.w - x * other.y + y * other.x + w * other.z,
          w * other.w + x * other.x + y * other.y + z * other.z);

  Quaternion conjugate() =>
      Quaternion(x, y, -z, w);

  double norm() => (x * x + y * y + z * z + w * w);

  Quaternion normalized() {
    double n = norm();
    return Quaternion(x / n, y / n, z / n, w / n);
  }

  Quaternion inverse() =>
      Quaternion(x, y, z, w) * conjugate() * (1 / norm());

  Quaternion rotate(Vector3 axis, double angle) {
    Quaternion q = Quaternion.fromAxisAngle(angle, axis);
    return q * this * q.inverse();
  }

  @override
  String toString() {
    return 'q1 = ${x.toStringAsFixed(2)} + $y * i + $z * j + $w * k';
  }
}

