class Quaternion {
  double x, y, z, w; 
  Quaternion(this.x, this.y, this.z, this.w);

  void conjugate() {
    x = x.abs();
    y = y.abs();
    z = z.abs();
    w = -w.abs();
  }

  void normalize() {
    final norm = x * x + y * y + z * z + w * w;
    if (norm == 0) {
      x = 0;
      y = 0;
      z = 0;
      w = 0;
      return;
    }
    x = x / norm;
    y = y / norm;
    z = z / norm;
    w = w / norm;
  }

  Quaternion operator +(Quaternion other) => Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator -(Quaternion other) => Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(Quaternion other) => Quaternion(x * other.w - y * other.z - z * other.y + w * other.x, 
                                                  y * other.w + x * other.z + z * other.y + w * other.w, 
                                                  z * other.w - x * other.y - y * other.x + w * other.z, 
                                                  w * other.w);

  Quaternion operator *=(Quaternion other) {
    x = x * other.w - y * other.z - z * other.y + w * other.x;
    y = y * other.w + x * other.z + z * other.y + w * other.w;
    z = z * other.w - x * other.y - y * other.x + w * other.z;
    w = w * other.w;
  }

  Quaternion operator ^(int rotations) {
    Quaternion q = this;
    for (int i = 0; i < rotations; i++) {
      q *= this;
    }
    return q;
  }

  Quaternion inverse() {
    double inv = 1 / (x * x + y * y + z * z + w * w);
    return Quaternion(inv * x, inv * y, inv * z, -inv * w);
  }

  void rotateAxis(double angle, List<double> axis) {
    double sinA = sin(angle);
    double cosA = cos(angle);
    double x1 = axis[0], y1 = axis[1], z1 = axis[2];

    x = x * cosA + z1 * sinA;
    y = y * cosA + y1 * sinA;
    z = z1 * cosA - x1 * sinA;
    w = w;
  }
}

