          realPart[0] * sin(angle / 2) +
              imaginaryPart[0] * cos(angle / 2),
          realPart[1] * cos(angle / 2) +
              imaginaryPart[1] * sin(angle / 2),
          realPart[1] * sin(angle / 2) -
              imaginaryPart[1] * cos(angle / 2));
