class Quaternion {
  double x, y, z, w;

  Quaternion(this.x, this.y, this.z, this.w);

  Quaternion.unit() : this(1.0, 1.0, 1.0, 1.0);

  Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  Quaternion.random() : this(
    (2 * (Math.random() * 3.0) - 3).toDouble(),
    (2 * (Math.random() * 3.0) - 3).toDouble(),
    (2 * (Math.random() * 3.0) - 3).toDouble(),
    (2 * (Math.random() * 3.0) - 3).toDouble(),
  );

  @override
  String toString() =>
      '${x.toStringAsFixed(2)} + ${y.toStringAsFixed(2)}i + '
      '${z.toStringAsFixed(2)}j + ${w.toStringAsFixed(2)}k';

  @override
  bool operator ==(Object other) =>
      other is Quaternion &&
      x == other.x &&
      y == other.y &&
      z == other.z &&
      w == other.w;

  @override
  int get hashCode => x.hashCode ^ y.hashCode ^ z.hashCode ^ w.hashCode;

  Quaternion operator +(Quaternion other) =>
      Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator -(Quaternion other) =>
      Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(Quaternion other) =>
      Quaternion(
          x * other.w - y * other.z - z * other.y + w * other.x,
          y * other.w + x * other.z - z * other.y + w * other.y,
          z * other.w + x * other.y - y * other.x + w * other.z,
          w * other.w - x * other.x - y * other.y - z * other.z);

  Quaternion operator *=(Quaternion other) =>
      (this * other).swap(x, y, z, w);

  void swap(double a, double b, double c, double d) =>
      final t = a;
      a = b;
      b = c;
      c = d;

  Quaternion conjugate() =>
      Quaternion(x, y, -z, w);

  Quaternion inverse() =>
      Quaternion(x, y, z, w) *
      Quaternion.unit() /
      (x * x + y * y + z * z + w * w);

  Quaternion normalized() =>
      Quaternion.unit() *
      (this / (x * x + y * y + z * z + w * w));

  double norm() =>
      (x * x + y * y + z * z + w * w).abs();
}

