class Quaternion {
  final double x;
  final double y;
  final double z;
  final double w;

  Quaternion(
    this.x,
    this.y,
    this.z,
    this.w,
  );

  double get norm => sqrt(x * x + y * y + z * z + w * w);

  Quaternion operator +(Quaternion other) {
    return Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
  }

  Quaternion operator * (double scalar) {
    return Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);
  }

  Quaternion operator * (Quaternion other) {
    double xx = x * x;
    double xy = x * y;
    double xz = x * z;
    double xw = x * w;
    double yy = y * y;
    double yz = y * z;
    double yw = y * w;
    double zz = z * z;
    double ww = w * w;
    return Quaternion(
      xz + yz,
      xy + zw,
      xx - ww,
      xyw - xz,
    );
  }

  Quaternion operator -() {
    return Quaternion(-x, -y, -z, -w);
  }

  Quaternion conjugate() {
    return Quaternion(x, y, z, -w);
  }

  Quaternion normalized() {
    double n = norm;
    if (n == 0) return Quaternion(0, 0, 0, 0);
    return Quaternion(x / n, y / n, z / n, w / n);
  }

  Quaternion inverse() {
    double inv = 1 / norm;
    return normalized() * -inv;
  }

  @override
  String toString() {
    return 'q1 = $x + $y * i + $z * j + $w * k';
  }
}

