  List<int> generateCombinations(List<int> arr, int start, int end) {
    List<int> result = [];
    if (start == end) {
      result.add(arr[start]);
    } else {
      for (int i = start; i < end; i++) {

        int temp = arr[start];
        arr[start] = arr[i];
        arr[i] = temp;

