    List<int> current = List.from(arr);

    int limit = end - start + 1;

    while (current.length < limit) {

      printCombinations(current);

      int i = current.length;
      while (i < limit && arr[i] == current[i]) {
        i++;
      }
      if (i < limit) {
        current.add(arr[i]);
      }

      int j = i;
      while (j < limit && arr[j] == current[j]) {
        j++;
      }
      for (int k = i; k < j; k++) {
        current[k] = current[i];
      }
      i = j;
    }
  }

