Map<String, int> fn0(List<String> inventory, int capacity) {
  if (inventory.isEmpty) return {};
  int rows = inventory.length;
  int cols = inventory[0].length;
  List<List<bool>> visited = List.generate(rows, (_) => List.filled(cols, false));
  List<int> dist = List.filled(rows, 0);
  List<String> parents = List.generate(rows, (_) => List.filled(cols, ''));
  List<List<int>> queue = [
    [0, 0]
  ];
  dist[0][0] = 1;
  visited[0][0] = true;
  while (queue.isNotEmpty) {
    List<int> curr = queue.removeAt(0);
    int r = curr[0], c = curr[1];
    for (int dr = -1; dr <= 1; dr++) {
      for (int dc = -1; dc <= 1; dc++) {
        int nr = r + dr;
        int nc = c + dc;
        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
          if (!visited[nr][nc]) {
            if (inventory[nr][nc] != '' && dr == 0 && dc == 0) {
              parents[nr][nc] = 'S';
            } else if (inventory[nr][nc] == '' || dr.abs() + dc.abs() > capacity) {
              dist[nr][nc] = dist[r][c] + 1;
              parents[nr][nc] = dr == 0 ? 'U' : dc == 0 ? 'R' : 'S';
              visited[nr][nc] = true;
              queue.add([nr, nc]);
            }
          }
        }
      }
    }
  }
  Map<String, int> result = {};
  int r = rows - 1, c = cols - 1;
  while (r > 0 || c > 0) {
    if (r > 0) result[parents[r - 1][c]] = dist[r - 1][c];
    if (c > 0) result[parents[r][c - 1]] = dist[r][c - 1];
    r--;
    c--;
  }
  return result;
}

