    moistureLevels[label] = count;
  }
  double center = (low + high) / 2.0;
  String label = center.toStringAsFixed(1) + ' ' + (center == low ? 'D' : 'H');
  int count = 0;
  for (var row in grid) {
    for (var moisture in row) {
      if (moisture >= center) count++;
    }
  }
  moistureLevels[label] = count;
  return moistureLevels;
}

