  void endiannessExample() {

    String byteStream = '';
    int value = 0x12345678;
    int shift = 4;

    for (int i = 0; i < 4 * 2; i++) {
      int byte = (value >> (i * 8)) & 0xFF;
      String hex = byte.toRadixString(16).toUpperCase().padLeft(2, '0').padRight(2, ' ');
      byteStream += hex;
    }

    String rotated = ((value << shift) | (value >> (32 - shift))) & 0xFFFFFFFF;
    int rotatedValue = rotated;

    String rotatedHex = '';
    for (int i = 0; i < 4 * 2; i++) {
      int byte = (rotatedValue >> (i * 8)) & 0xFF;
      String hex = byte.toRadixString(16).toUpperCase().padLeft(2, '0').padRight(2, ' ');
      rotatedHex += hex;
    }

    print('Byte stream (BE): [${byteStream}]');
    print('Original value: 0x${value.toRadixString(16).toUpperCase().padLeft(4, "0")}');
    print('Rotate by ${shift}: 0x${rotatedValue.toRadixString(16).toUpperCase().padLeft(4, "0")}');
    print('Binary: ${byteStream.toUpperCase()}');
    print('Hex: ${rotatedHex.toUpperCase()}');

    bool swap = (value & 0x80000000) != 0;
    String swapped = swap
        ? ((value << 16) | ((value >> 16) & 0xFF)) & 0xFFFF
        : ((value >> 16) | ((value << 16) & 0xFFFF)) & 0xFFFF;

    print('\n16-bit swap of 0x${value.toRadixString(16).toUpperCase().padLeft(4, "0")}');
    print('Swap back: 0x${swapped.toRadixString(16).toUpperCase().padLeft(4, "0")}');
  }

  void floatEndiannessExample() {

    double value = 3.14159;
    String floatBinary = '';
    List<int> bytes = [];

    void floatToBytes(double value, int size, List<int> bytes) {
      int* data = (value * (1 << size)) & 0xFFFFFFFF;
      bytes[0] = (data >> 24) & 0xFF;
      bytes[1] = (data >> 16) & 0xFF;
      bytes[2] = (data >> 8) & 0xFF;
      bytes[3] = data & 0xFF;
    }

    floatToBytes(value, 32, bytes);

    for (int i = 0; i < 4 * 2; i++) {
      int byte = bytes[i];
      String hex = byte.toRadixString(16).toUpperCase().padLeft(2, '0').padRight(2, ' ');
      floatBinary += hex;
    }

    print('Float value: ${value.toStringAsFixed(32)}');
    print('Binary: ${floatBinary.toUpperCase()}');
    print('As Little Endian bytes: [${bytes[3]},${bytes[2]},${bytes[1]},${bytes[0]}');
    print('As Big Endian bytes:   [${bytes[0]},${bytes[1]},${bytes[2]},${bytes[3]}');
  }

  void networkByteOrderExample() {

    String byteStream = '';
    int value = 0x12345678;

    for (int i = 0; i < 4 * 2; i++) {
      int byte = (value >> (i * 8)) & 0xFF;
      String hex = byte.toRadixString(16).toUpperCase().padLeft(2, '0').padRight(2, ' ');
      byteStream += hex;
    }

    String reversed = ((value >> 0) & 0xFF) | ((value << 24) & 0xFF) | ((value >> 8) & 0xFF) | ((value >> 16) & 0xFF);
    int reversedValue = reversed;

    print('Network bytes: [${byteStream}]');
    print('Original value: 0x${value.toRadixString(16).toUpperCase().padLeft(4, "0")}');
    print('Reverse order: 0x${reversedValue.toRadixString(16).toUpperCase().padLeft(4, "0")}');
    print('Binary: ${byteStream.toUpperCase()}');
    print('Hex: ${byteStream.toUpperCase().padLeft(8, "0")}');
  }

  void arrayEndiannessConversion() {

    int value = 0x12345678;

    List<int> hostValues = [value];
    List<int> networkValues = [];

    void toNetworkOrder(List<int> values, List<int> network) {
      for (int i = 0; i < values.length; i++) {
        int byte = values[i] & 0xFF;
        network.add(byte);
        if (i > 0) {
          network.add((byte >> 4) & 0xFF);
        }
      }
    }

    toNetworkOrder(hostValues, networkValues);

    print('Array Endianness Conversion:');
    print('Original value: 0x${value.toRadixString(16).toUpperCase().padLeft(4, "0")}');
    print('As Little Endian bytes: [${networkValues.map((v) => v.toRadixString(16).padLeft(2, '0')).join(", ")}]');
    print('As Big Endian bytes:   [${networkValues.map((v) => v.toRadixString(16).padLeft(2, '0')).reversed.join(", ")}]');
  }

  void endiannessSwapping() {

    int value = 0x12345678;
    int swapped = ((value >> 8) & 0xFF) | ((value << 24) & 0xFF) | ((value >> 0) & 0xFF) | ((value >> 16) & 0xFF);
    int swappedValue = swapped;

    print('Endianness Swapping:');
    print('Original value: 0x${value.toRadixString(16).toUpperCase().padLeft(4, "0")}');
    print('Swap back: 0x${swappedValue.toRadixString(16).toUpperCase().padLeft(4, "0")}');
  }

  getSystemInfo();
  endiannessExample();
  floatEndiannessExample();
  networkByteOrderExample();
  arrayEndiannessConversion();
  endiannessSwapping();
}

