  final supportCounts = <String, int>{};

  for (final itemset in transactions) {
    final items = itemset.toSet();
    for (var k = 1; k <= 2; k++) {
      final prefix = items.toList().sublist(0, k);
      final prefixSet = prefix.toSet();

      int frequentCount = 0;
      for (final trans in transactions) {
        if (trans.toSet().contains(prefixSet)) {
          frequentCount++;
        }
      }

      final confidence = frequentCount / transactions.length;

      if (confidence >= minSupport) {
        frequentItemsets.add(prefixSet);
        supportCounts[prefixSet.join(' | ')] = frequentCount;
      }
    }
  }

  print('Frequent Itemsets:');
  print(frequentItemsets.join(' | '));

