      final itemset = frequentItemsetsList[j];

      if (itemset.length >= i) {
        final itemsetPrefix = itemset.sublist(0, i).toList();
        final itemsetPrefixSet = itemsetPrefix.toSet();

        bool hasSupport = false;
        for (final trans in transactions) {
          if (trans.toSet().contains(itemsetPrefixSet)) {
            hasSupport = true;
            break;
