Map<String, int> fn0(List<int> actualVotes, List<int> expectedVotes, int threshold) {
  int totalDeficitDays = 0;
  int longestInterval = 0;
  int distinctIntervals = 0;

  if (actualVotes.isEmpty || expectedVotes.isEmpty) {
    return {
      'totalDeficitDays': 0,
      'longestInterval': 0,
      'distinctIntervals': 0,
    };
  }

  List<int> intervals = [];
  int expectedIdx = 0;
  int actualIdx = 0;

  while (actualIdx < actualVotes.length) {
    int expectedVal = expectedVotes[expectedIdx];
    int actualVal = actualVotes[actualIdx];

    if (actualVal >= threshold) {
      if (expectedVal >= threshold) {
        if (actualVal == expectedVal) {
          if (intervals.isNotEmpty && intervals.last == 0) {
            intervals.removeLast();
          }
        } else {
          intervals.add(expectedVal - actualVal);
        }
      } else {
        if (intervals.isNotEmpty) {
          intervals.add(intervals.last);
        }
      }
      expectedIdx++;
      actualIdx++;
    } else {
      actualIdx++;
    }
  }

  if (expectedIdx < expectedVotes.length) {
    int leftover = expectedVotes.length - expectedIdx;
    totalDeficitDays += leftover;
    for (int i = 0; i < leftover; i++) {
      intervals.add(0);
    }
  }

  for (int i = 0; i < intervals.length; i++) {
    if (intervals[i] > longestInterval) {
      longestInterval = intervals[i];
    }
  }

  distinctIntervals = (intervals.length + 1) ~/ 2;

  return {
    'totalDeficitDays': totalDeficitDays,
    'longestInterval': longestInterval,
    'distinctIntervals': distinctIntervals,
  };
}

