Map<String, int> fn0(List<int> schedule) {
  int n = schedule.length;
  if (n == 0) return {"longestInterval": -1, "totalDeficitDays": -1, "distinctIntervals": 0};

  List<int> dp = List.filled(n + 1, 1 << 30);
  dp[0] = 0;

  List<int> distinctIntervals = [];
  for (int i = 1; i <= n; i++) {
    for (int j = 0; j < i; j++) {
      if (schedule[i - 1] >= schedule[j]) {
        int cost = dp[j] + schedule[i - 1] - schedule[j];
        if (cost < dp[i]) {
          dp[i] = cost;
        }
      }
    }
    if (dp[i] != 1 << 30) {
      distinctIntervals.add(dp[i]);
    }
  }

  int longestInterval = -1;
  for (int interval in distinctIntervals) {
    if (interval > longestInterval) {
      longestInterval = interval;
    }
  }

  int totalDeficitDays = 0;
  for (int i = 1; i <= n; i++) {
    if (dp[i] != 1 << 30) {
      totalDeficitDays += schedule[i - 1] - dp[i];
    }
  }

  return {"longestInterval": longestInterval, "totalDeficitDays": totalDeficitDays, "distinctIntervals": distinctIntervals.length};
}

