Map<String, int> fn0(List<int> dailyCounts, int reserve) {
  int n = dailyCounts.length;
  if (n == 0) return {'longestInterval': -1, 'totalDeficitDays': 0, 'distinctIntervals': 0};
  List<int> prefix = List<int>.filled(n + 1, 0);
  for (int i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + dailyCounts[i] - reserve;
  }
  int longest = 0, current = 0, distinct = 0;
  int i = 0;
  while (i < n) {
    while (i < n && prefix[i + 1] < 0) i++;
    if (i >= n) break;
    int j = i;
    while (j < n && prefix[j + 1] >= 0) j++;
    int span = j - i;
    if (span > longest) longest = span;
    if (span > 0 && span != current) {
      current = span;
      distinct++;
    }
    i = j;
  }
  return {'longestInterval': longest, 'totalDeficitDays': prefix[n], 'distinctIntervals': distinct};
}

