Map<String, int> fn0(List<int> dailyNet, int startDayIndex, int numDays) {
  int totalDeficit = 0;
  int longestInterval = 0;
  int distinctIntervals = 0;
  List<int> windowSum = [];
  int n = dailyNet.length;
  if (n == 0 || numDays <= 0) return {'totalDeficitDays': 0, 'longestInterval': 0, 'distinctIntervals': 0};

  for (int i = startDayIndex; i < startDayIndex + numDays; i++) {
    if (i >= 0 && i < n) {
      windowSum.add(dailyNet[i]);
    }
  }

  if (windowSum.isEmpty) return {'totalDeficitDays': 0, 'longestInterval': 0, 'distinctIntervals': 0};

  int left = 0;
  int right = windowSum.length - 1;
  int currentSum = 0;

  while (left <= right) {
    int mid = left + ((right - left) >> 1);
    int sum = 0;
    for (int i = 0; i <= mid; i++) {
      sum += windowSum[i];
    }

    if (sum > currentSum) {
      currentSum = sum;
      right = mid - 1;
    } else {
      left = mid + 1;
    }
  }

  totalDeficit = currentSum - windowSum.first;

  int n1 = windowSum.length;
  for (int i = 0; i < n1; i++) {
    for (int j = i + 1; j < n1; j++) {
      if (j - i > longestInterval) {
        longestInterval = j - i;
      }
      if (i > 0 && windowSum[i] == windowSum[j]) {
        distinctIntervals++;
      }
    }
  }

  return {'totalDeficitDays': totalDeficit, 'longestInterval': longestInterval, 'distinctIntervals': distinctIntervals};
}

