Map<String, int> fn0(List<int> deliveryDays, int startDayIndex) {
  int n = deliveryDays.length;
  if (n == 0) return {'longestInterval': -1, 'distinctIntervals': 0, 'totalDeficitDays': 0};
  int currentInterval = 0;
  int maxInterval = 0;
  List<int> intervals = [];
  for (int i = 0; i < n; i++) {
    int gap = deliveryDays[i] - startDayIndex;
    if (gap >= 0) {
      currentInterval++;
      if (currentInterval > maxInterval) maxInterval = currentInterval;
    } else {
      currentInterval = 1;
    }
    if (i > 0 && deliveryDays[i] == deliveryDays[i - 1]) {
      currentInterval--;
    } else if (i > 0 && deliveryDays[i] != deliveryDays[i - 1]) {
      intervals.add(currentInterval);
    }
  }
  if (n > 1) {
    int lastGap = deliveryDays[n - 1] - startDayIndex;
    if (lastGap >= 0) {
      currentInterval++;
      if (currentInterval > maxInterval) maxInterval = currentInterval;
    } else {
      currentInterval = 1;
    }
    if (n > 2 && deliveryDays[n - 1] == deliveryDays[n - 2]) {
      currentInterval--;
    } else if (n > 2 && deliveryDays[n - 1] != deliveryDays[n - 2]) {
      intervals.add(currentInterval);
    }
  }
  int totalDeficit = 0;
  for (int v in intervals) {
    if (v > 1) {
      totalDeficit += (v - 1) * startDayIndex;
    }
  }
  return {'longestInterval': maxInterval, 'distinctIntervals': intervals.length, 'totalDeficitDays': totalDeficit};
}

