Map<String, int> fn0(List<int> dailyCounts, int threshold) {
  if (dailyCounts.isEmpty || threshold <= 0) {
    return {'longestInterval': -1, 'totalDeficitDays': 0, 'distinctIntervals': 0};
  }

  List<int> counts = [];
  for (int day = 0; day < dailyCounts.length; day++) {
    if (dailyCounts[day] < threshold) {
      counts.add(day);
    }
  }

  int longestInterval = 0;
  for (int i = 0; i < counts.length - 1; i++) {
    int gap = counts[i + 1] - counts[i];
    if (gap > longestInterval) longestInterval = gap;
  }

  int totalDeficitDays = 0;
  for (int day in counts) {
    totalDeficitDays += threshold - dailyCounts[day];
  }

  int distinctIntervals = 0;
  for (int i = 0; i < counts.length - 1; i++) {
    for (int j = i + 1; j < counts.length; j++) {
      int gap = counts[j] - counts[i];
      if (gap > 0 && !counts.contains(gap)) {
        distinctIntervals++;
        break;
      }
    }
  }

  return {'longestInterval': longestInterval, 'totalDeficitDays': totalDeficitDays, 'distinctIntervals': distinctIntervals};
}

