class Point<T> {
  final T x;
  final T y;

  const Point(this.x, this.y);

  @override
  String toString() => 'Point($x, $y)';

  T get x => x;
  T get y => y;

  double distance(Point<T> other) => sqrt(pow(x - other.x, 2) + pow(y - other.y, 2));
}

class Rectangle<T> {
  final Point<T> center;
  final T width;
  final T height;

  Rectangle(this.center, this.width) : this(center, width, width);

  Rectangle(this.center, this.width, this.height);

  Rectangle<T> translate(T dx, T dy) => Rectangle(center + Point(dx, dy), width, height);

  Rectangle<T> scale(T sx, T sy) => Rectangle(center + Point(sx, sy), sx, sy);

  Rectangle<T> get intersection => Rectangle(center, width, height);

  bool contains(Point<T> p) => p.x >= center.x - width &&
                                p.x <= center.x + width &&
                                p.y >= center.y - height &&
                                p.y <= center.y + height;

  @override
  String toString() => 'Rectangle(center: (${center.x}, ${center.y}), halfWidth: ${width}, halfHeight: ${height})';
}

