Set<int> fn0(String maze, int startRow, int startCol) {
  List<List<int>> directions = [
    [0, 1], [0, -1], [1, 0], [-1, 0]
  ];

  List<List<int>> explore(int r, int c, List<String> wallSymbols) {
    List<List<int>> result = [];

    for (var d in directions) {
      int nr = r + d[0];
      int nc = c + d[1];

      if (nr >= 0 && nr < maze.length && nc >= 0 && nc < maze[nr].length) {
        String cell = maze[nr][nc];
        if (!wallSymbols.contains(cell)) {
          result.add([nr, nc]);
        }
      }
    }

    return result;
  }

  List<List<int>> queue = [[startRow, startCol]];
  Set<int> visited = {};

  while (queue.isNotEmpty) {
    List<int> current = queue.removeAt(0);
    int r = current[0];
    int c = current[1];

    if (!visited.contains(r * maze.length + c)) {
      visited.add(r * maze.length + c);

      List<List<int>> neighbors = explore(r, c, wallSymbols);
      for (var n in neighbors) {
        queue.add(n);
      }
    }
  }

  return visited;
}

