bool fn0(List<List<int>> modules) {
  if (modules.isEmpty || modules[0].isEmpty) return false;
  int cols = modules[0].length;
  List<List<int>> counts = List.generate(cols, (_) => List.filled(cols, 0));
  int maxCount = 0;
  for (int i = 0; i < modules.length - 1; i++) {
    for (int j = 0; j < cols; j++) {
      int v = modules[i][j];
      if (v == 0) continue;
      bool hasNeighbor = false;
      for (int d = 0; d < 4; d++) {
        int ni = i + v.direction[d];
        int nj = j + v.direction[d];
        if (ni >= 0 && ni < modules.length && nj >= 0 && nj < cols && modules[ni][nj] == v) {
          hasNeighbor = true;
          break;
        }
      }
      if (!hasNeighbor) {
        if (v >= 1) continue;
        counts[j][i]++;
      } else {
        counts[j][i] = counts[j][i] + v;
        if (counts[j][i] > maxCount) maxCount = counts[j][i];
      }
    }
  }
  Map<int, int> groups = {};
  for (int i = 0; i < cols; i++) {
    for (int j = 0; j < modules.length - 1; j++) {
      int v = counts[i][j];
      if (v == 0) continue;
      groups.putIfAbsent(v, () => <int>[j, i]);
    }
  }
  for (int v = 1; v <= maxCount; v++) {
    var group = groups[v];
    if (group == null || group.length != 2) return false;
    int ri = group[0];
    int ci = group[1];
    for (int r = 0; r < modules.length - 1; r++) {
      if (r != ri) continue;
      for (int c = 0; c < cols; c++) {
        if (c != ci) continue;
        int v2 = counts[c][r];
        if (v2 != v) return false;
      }
    }
  }
  return true;
}

