bool fn0(List<String> items, int minStock) {
  if (items.isEmpty) return true;
  if (items.length == 1) return items[0].length > minStock;

  List<String> sublists = [];
  int mid = items.length ~/ 2;

  for (int i = 0; i < items.length; i++) {
    if (i < mid) sublists.add(items[i]);
  }

  Map<String, int> prefixSums = {};
  for (int i = 0; i < sublists.length; i++) {
    prefixSums[sublists[i]] = (prefixSums[sublists[i]] ?? 0) + 1;
  }

  for (int j = 0; j < sublists.length; j++) {
    int count = prefixSums[sublists[j]]!;
    if (count <= minStock) continue;

    List<String> leftSublists = [];
    for (int k = 0; k < sublists.length; k++) {
      if (k != j) leftSublists.add(sublists[k]);
    }

    bool leftValid = fn0(leftSublists, minStock - count);
    bool rightValid = fn0(sublists.sublist(j + 1), minStock - count);
    return leftValid && rightValid;
  }

  return false;
}

