  for (String pass in passes) {
    int dashCount = pass.split('').where((c) => c == '-').length;
    freq[dashCount] = (freq[dashCount] ?? 0) + 1;
  }
  int maxFreq = 0;
  for (int count in freq.values) {
    if (count > maxFreq) maxFreq = count;
  }
  List<int> maxPasses = [];
  for (int count in freq.values) {
    if (count == maxFreq) maxPasses.add(0);
