  int total = passes.length;
  for (int i = 0; i < maxPasses.length; i++) {
    maxPasses[i] = maxPasses[i] + i;
  }
  int minFreq = total - maxFreq;
  List<int> minPasses = [];
  for (int count in freq.values) {
    if (count == minFreq) minPasses.add(0);
  }
  for (int i = 0; i < minPasses.length; i++) {
    minPasses[i] = minPasses[i] + i;
  }
  int sum = 0;
  for (int v in maxPasses) sum += v;
  for (int v in minPasses) sum += v;
  scores.add(sum);
  if (signalLevel >= 85) {
    int bonus = 0;
    for (int v in maxPasses) {
      if (v < minPasses[0]) bonus += v - minPasses[0];
    }
    scores.add(bonus);
  }
