List<int> fn0(List<int> moisture, int threshold) {
  if (moisture.isEmpty) return [];
  int n = moisture.length;
  int left = 0;
  int right = n - 1;
  int ans = n;
  while (left <= right) {
    int mid = left + ((right - left) >> 1);
    int sum = 0;
    for (int i = 0; i <= mid; i++) {
      if (moisture[i] >= threshold) sum += moisture[i];
    }
    if (sum >= mid * threshold) {
      ans = mid;
      right = mid - 1;
    } else {
      left = mid + 1;
    }
  }
  int bestStart = ans;
  int bestEnd = n - 1;
  for (int i = n - 1; i >= 0; i--) {
    if (moisture[i] >= threshold) {
      int sum = 0;
      for (int j = i; j <= bestEnd; j++) {
        if (moisture[j] >= threshold) sum += moisture[j];
      }
      if (sum >= i * threshold) {
        bestStart = i;
        bestEnd = j - 1;
      }
    }
  }
  return [bestStart, bestEnd];
}

