    for (int i = start; i <= end; i++) {
      yield i;
    }
  }

  Stream<int> evenNumbers(int start, int end) async* {
    for (int i = start; i <= end; i++) {
      if (i.isEven) yield i;
    }
  }

  Stream<int> oddNumbers(int start, int end) async* {
    for (int i = start; i <= end; i++) {
      if (i.isOdd) yield i;
    }
  }

  print('Starting combined odd number stream...');
  Stream<int> combined = numbers(1, 4)..addAll(evenNumbers(5, 8))..addAll(oddNumbers(9, 12));

  await for (var number in combined) {
    print('Odd number: $number');
  }

  print('Stream processing complete.');
}

import 'dart:async';
import 'dart:convert';
import 'dart:math';

/// A Dart program demonstrating async* streams combined with generators.
/// The main function uses async* streams to yield odd numbers from 1 to 10.
/// The async* generator yields numbers that are multiples of 3 from 3 to 30.

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() async {

  Stream<int> naturalNumbers() async* {
    for (int i = 1; i <= 10; i++) {
      yield i;
    }
  }

  Stream<int> multiplesOfThree() async* {
    yield 3;
    yield* Stream<int>.generate(7, (i) => i * 3);
  }

  Stream<int> combinedOddNumbers() async* {
    yield 1;
    yield 3;
    yield* naturalNumbers(); 
    yield* multiplesOfThree(); 
    yield* Stream<int>.generate(7, (i) => i * 3);
  }

  print('Starting combined odd number stream...');
  await for (var number in combinedOddNumbers()) {
    print('Odd number: $number');
  }
  print('Stream processing complete.');
}

