import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Future<void> fn0() async {

  Stream<int> oddNumbers(int max) async* {
    for (int i = 1; i <= max; i += 2) {
      yield i;
    }
  }

  Stream<int> evenNumbers(int max) async* {
    for (int i = 2; i <= max; i += 2) {
      yield i;
    }
  }

  Stream<int> combinedOddNumbers(int max) async* {
    yield 1; 
    yield* oddNumbers(max); 
    yield 3; 
    yield* evenNumbers(max); 
    yield 5; 
  }

  print('Starting combined odd number stream...');
  await for (var number in combinedOddNumbers(5)) {
    print('Odd number: $number');
  }
  print('Stream processing complete.');
}

