bool fn0(List<int> tideReadings) {
  int left = 0;
  int right = tideReadings.length - 1;
  while (left <= right) {
    int mid = (left + right) >> 1;
    bool rising = true;
    for (int i = 0; i < mid; i++) {
      if (tideReadings[i] > tideReadings[mid]) {
        rising = false;
        break;
      }
    }
    if (rising) return true;
    if (tideReadings[mid] < tideReadings[0]) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }
  return false;
}

