@pragma('vm:never-inline')
@pragma('vm:entry-point')

bool fn0(List<List<int>> points, int minDist) {
  int n = points.length;
  if (n < 2) return true;
  int total = 0;
  for (int i = 0; i < n - 1; i++) {
    for (int j = i + 1; j < n; j++) {
      int d = (points[i][0] - points[j][0]).abs() + (points[i][1] - points[j][1]).abs();
      if (d >= minDist) {
        total++;
      }
    }
  }
  return total == n - 1;
}

