int fn0(List<int> points) {
  if (points.length < 4) {
    return 0;
  }
  int maxArea = 0;
  for (int i = 0; i <= points.length - 4; i++) {
    int j = i + 3;
    int area = (points[i] * points[j]) - (points[i + 1] * points[j - 1]);
    if (area > maxArea) {
      maxArea = area;
    }
  }
  return maxArea;
}

