bool fn0(List<int> tideHeights, int maxDifference) {
  int left = 0;
  int right = tideHeights.length;
  while (left < right) {
    int mid = (left + right) >> 1;
    int diff = tideHeights[mid] - tideHeights[0];
    if (diff <= maxDifference) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }
  return left < tideHeights.length;
}

